import{initializeApp}from'https://www.gstatic.com/firebasejs/11.0.2/firebase-app.js';
import{getAuth,onAuthStateChanged,signInWithEmailAndPassword,signOut}from'https://www.gstatic.com/firebasejs/11.0.2/firebase-auth.js';
import{getFirestore,doc,onSnapshot,setDoc,getDoc}from'https://www.gstatic.com/firebasejs/11.0.2/firebase-firestore.js';
import{getFunctions,httpsCallable}from'https://www.gstatic.com/firebasejs/11.0.2/firebase-functions.js';
import{firebaseConfig}from'./firebase-config.js';
const ADMINS=['nikkhaikal@gmail.com','nealia.najihah@gmail.com'],scoreRows=['Keyin','Net','Recruitment:','NAHP','AHP','Total HP','T/O','SHI Group','SHI Personal','WS Player'],hpRows=['Keyin','Net','Recruitment:','NAHP','AHP','Total HP','T/O','SHI Personal','WS Player'],months=['December','January','February','March','April','May'],app=initializeApp(firebaseConfig),auth=getAuth(app),db=getFirestore(app),functions=getFunctions(app),$=id=>document.getElementById(id);let state={},canEdit=false,stopListening,saveTimer;const manager=email=>ADMINS.includes((email||'').toLowerCase());function message(id,text='',type=''){const e=$(id);e.textContent=text;e.className=`message ${type}`}function rows(id,list,key){$(id).innerHTML=list.map((name,i)=>`<tr><td data-key="${key}-${i}-label">${state[`${key}-${i}-label`]||name}</td><td class="target" data-key="${key}-${i}-target">${state[`${key}-${i}-target`]||'—'}</td><td class="actual" data-key="${key}-${i}-actual">${state[`${key}-${i}-actual`]||'—'}</td></tr>`).join('')}function save(){clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{await setDoc(doc(db,'dashboards','main'),state)}catch(e){message('authMessage',e.message,'error')}},500)}function render(){rows('scoreTable',scoreRows,'score');rows('hpTable',hpRows,'hp');$('monthlyPlan').innerHTML=months.map((m,i)=>`<div class="plan-item"><strong>${m}</strong><span data-key="month-${i}">${state[`month-${i}`]||'Add monthly focus'}</span></div>`).join('');document.querySelectorAll('[data-key]').forEach(c=>{c.contentEditable=canEdit;c.addEventListener('input',()=>{state[c.dataset.key]=c.textContent.trim();save()})});$('editBtn').disabled=!canEdit;$('editBtn').textContent=canEdit?'Editing enabled':'View only'}function watch(){stopListening?.();stopListening=onSnapshot(doc(db,'dashboards','main'),s=>{state=s.exists()?s.data():{};render()},e=>message('authMessage',e.message,'error'))}$('signIn').onclick=async()=>{try{message('authMessage');await signInWithEmailAndPassword(auth,$('email').value.trim(),$('password').value)}catch(e){message('authMessage','Sign-in failed. Check your email and password.','error')}};$('signOut').onclick=()=>signOut(auth);$('createAccount').onclick=async()=>{try{const r=await httpsCallable(functions,'createAccount')({name:$('newName').value.trim(),email:$('newEmail').value.trim(),role:$('newRole').value});message('accountMessage',`Account created for ${r.data.email}. Temporary password: ${r.data.temporaryPassword}`,'success');$('newName').value=$('newEmail').value=''}catch(e){message('accountMessage',e.message||'Could not create account.','error')}};onAuthStateChanged(auth,async u=>{const profile=u?await getDoc(doc(db,'users',u.uid)):null;canEdit=!!u&&(manager(u.email)||profile?.data()?.role==='editor');const canManage=!!u&&manager(u.email);$('login').style.display=u?'none':'grid';$('session').classList.toggle('show',!!u);$('accounts').classList.toggle('show',canManage);$('userLabel').textContent=u?`${u.email} · ${canManage?'Admin':canEdit?'Editor':'Viewer'}`:'';message('authMessage',u?'':'Sign in to view the shared dashboard.');if(u)watch();else{stopListening?.();state={};render()}});$('today').textContent=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(new Date());render();
